231:   if (!entries.length) {
232:     const empty = document.createElement("p");
233:     empty.className = "dna-empty";
234:     empty.textContent = "No genomes archived yet. Save the selected specimen to begin a lineage library.";
235:     els.dnaList.append(empty);
236:     return;
237:   }
238: 
239:   for (const entry of entries) {
240:     const card = document.createElement("article");
241:     card.className = "dna-entry";
242:     const details = document.createElement("div");
243:     details.className = "dna-entry-copy";
244:     const name = document.createElement("strong");
245:     name.textContent = entry.name;
246:     const meta = document.createElement("span");
247:     const date = new Date(entry.savedAt);
248:     meta.textContent = `${entry.latin || "Archived genome"} · G${pad(entry.generation || 1)} · ${Number.isNaN(date.getTime()) ? "saved previously" : date.toLocaleDateString()}`;
249:     details.append(name, meta);
