251:     const actions = document.createElement("div");
252:     actions.className = "dna-entry-actions";
253:     const restore = document.createElement("button");
254:     restore.className = "button button-quiet";
255:     restore.type = "button";
256:     restore.dataset.restoreGenome = entry.id;
257:     restore.textContent = "Restore";
