261:     remove.dataset.removeGenome = entry.id;
262:     remove.setAttribute("aria-label", `Remove ${entry.name} from DNA bank`);
263:     remove.textContent = "×";
264:     actions.append(restore, remove);
265:     card.append(details, actions);
266:     els.dnaList.append(card);
