301:   addLog(`Archived genome <b>${entry.name}</b> restored to specimen K-${pad(creatures.selectedIndex + 1)}.`, true);
302:   showToast("Genome restored", `${entry.name} now occupies the selected specimen`, "◈", 3000);
303:   audio.select();
