:root {
  --bg: #050e0c;
  --panel: rgba(7, 20, 17, 0.78);
  --panel-deep: rgba(4, 13, 11, 0.92);
  --line: rgba(184, 255, 213, 0.12);
  --line-strong: rgba(184, 255, 213, 0.22);
  --text: #edf7f1;
  --muted: #7e9c91;
  --faint: #547168;
  --lime: #c9ff66;
  --mint: #58f0c0;
  --cyan: #66e6ff;
  --coral: #ff916d;
  --amber: #ffcf72;
  --danger: #ff6f63;
