486:   buildArmor({ bodyLen, bodyW, bodyH, bodyY, legLen }) {
487:     const g = this.genome;
488:     if (g.armor < 0.22) return;
489:     const count = 3 + Math.round(g.armor * 5);
490:     for (let i = 0; i < count; i += 1) {
491:       const t = (i / (count - 1 || 1)) * 1.5 - 0.75;
492:       const z = t * bodyLen * 0.76;
493:       const profile = Math.sqrt(Math.max(0.06, 1 - Math.pow(t * 0.72, 2)));
494:       const height = (0.11 + g.armor * 0.26) * (0.7 + profile * 0.55);
495:       const spike = new THREE.Mesh(new THREE.ConeGeometry(0.045 + g.armor * 0.026, height, 4), this.boneMat);
496:       spike.position.set(0, bodyY + bodyH * profile * 0.93, z);
497:       spike.rotation.x = -0.34 - g.armor * 0.18;
498:       spike.rotation.y = Math.PI / 4;
499:       spike.castShadow = true;
500:       this.model.add(spike);
501:     }
502: 
503:     if (g.armor > 0.62) {
504:       for (const side of [-1, 1]) {
505:         const plate = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.18, 4), this.boneMat);
506:         plate.position.set(side * bodyW * 0.55, bodyY + bodyH * 0.5, bodyLen * 0.55);
507:         plate.rotation.z = side * 0.6;
508:         plate.rotation.x = -0.3;
509:         plate.castShadow = true;
510:         this.model.add(plate);
511:       }
512:     }
513:   }
514: 
515:   buildAccents({ bodyLen, bodyW, bodyH, bodyY }) {
516:     const g = this.genome;
517:     const spotCount = Math.round(1 + g.pattern * 5);
518:     for (let i = 0; i < spotCount; i += 1) {
519:       const side = i % 2 === 0 ? -1 : 1;
520:       const t = (i / Math.max(1, spotCount - 1)) * 1.4 - 0.7;
521:       const spot = new THREE.Mesh(new THREE.SphereGeometry(0.008 + g.pattern * 0.012, 6, 5), this.spotMat);
522:       spot.position.set(side * bodyW * 0.98, bodyY - bodyH * 0.05 + Math.sin(t * 3) * 0.03, t * bodyLen * 0.68);
523:       this.model.add(spot);
524:     }
525:   }
