263:   buildNeck({ bodyLen, bodyW, bodyH, bodyY, neckLen, accentColor }) {
264:     const g = this.genome;
265:     const neckGroup = new THREE.Group();
266:     neckGroup.position.set(0, bodyY + bodyH * 0.3, bodyLen * 0.69);
267:     neckGroup.rotation.x = 0.62 + g.neck * 0.2;
268:     this.model.add(neckGroup);
269:     this.neckGroup = neckGroup;
270: 
271:     const segCount = 4;
272:     for (let i = 0; i < segCount; i += 1) {
273:       const t = (i + 0.5) / segCount;
274:       const taper = 1 - t * 0.22;
275:       const segment = new THREE.Mesh(this.torsoGeo, this.bodyMat);
276:       const segLen = neckLen / segCount;
277:       segment.scale.set(
278:         (0.14 + g.neck * 0.022) * taper,
279:         segLen * 0.68,
280:         (0.135 + g.neck * 0.02) * taper,
281:       );
282:       segment.position.set(0, t * neckLen, Math.sin(t * Math.PI) * 0.035);
283:       segment.castShadow = true;
284:       neckGroup.add(segment);
285:     }
286: 
287:     const headGroup = new THREE.Group();
288:     headGroup.position.set(0, neckLen + 0.045, 0.085);
289:     headGroup.rotation.x = -0.54;
290:     neckGroup.add(headGroup);
291:     this.headGroup = headGroup;
292: 
293:     const headR = 0.205 + g.crest * 0.026;
294:     const cranium = new THREE.Mesh(this.torsoGeo, this.bodyMat);
295:     cranium.scale.set(headR * 1.02, headR * 0.9, headR * 1.28);
296:     cranium.castShadow = true;
297:     headGroup.add(cranium);
298: 
299:     const snout = new THREE.Mesh(this.torsoGeo, this.bodyMat);
300:     snout.scale.set(headR * 0.72, headR * 0.5, headR * 1.05);
301:     snout.position.set(0, -headR * 0.17, headR * 1.48);
302:     snout.castShadow = true;
303:     headGroup.add(snout);
304: 
305:     const jaw = new THREE.Mesh(this.torsoGeo, this.bellyMat);
306:     jaw.scale.set(headR * 0.62, headR * 0.24, headR * 0.88);
307:     jaw.position.set(0, -headR * 0.55, headR * 1.36);
308:     headGroup.add(jaw);
309: 
310:     const browRidge = new THREE.Mesh(this.torsoGeo, this.limbMat);
311:     browRidge.scale.set(headR * 0.84, headR * 0.18, headR * 0.52);
312:     browRidge.position.set(0, headR * 0.5, headR * 0.36);
313:     headGroup.add(browRidge);
314: 
315:     for (const side of [-1, 1]) {
316:       const eyeSocket = new THREE.Mesh(this.torsoGeo, this.bellyMat);
317:       eyeSocket.scale.set(headR * 0.35, headR * 0.3, headR * 0.32);
318:       eyeSocket.position.set(side * headR * 0.78, headR * 0.25, headR * 0.62);
319:       headGroup.add(eyeSocket);
320: 
321:       const eye = new THREE.Mesh(this.torsoGeo, this.eyeMat);
322:       eye.scale.setScalar(headR * 0.22);
323:       eye.position.set(side * headR * 0.89, headR * 0.28, headR * 0.72);
324:       eye.userData.baseScaleY = headR * 0.22;
325:       headGroup.add(eye);
326:       this.eyes.push(eye);
327: 
328:       const glint = new THREE.Mesh(new THREE.SphereGeometry(1, 7, 5), this.glintMat);
329:       glint.scale.setScalar(headR * 0.055);
330:       glint.position.set(side * headR * 0.94, headR * 0.34, headR * 0.86);
331:       headGroup.add(glint);
332: 
333:       if (g.armor > 0.42) {
334:         const brow = new THREE.Mesh(new THREE.ConeGeometry(headR * 0.14, headR * (0.26 + g.armor * 0.4), 4), this.boneMat);
335:         brow.position.set(side * headR * 0.74, headR * 0.58, headR * 0.46);
336:         brow.rotation.set(-0.4, 0, side * -0.4);
337:         brow.castShadow = true;
338:         headGroup.add(brow);
339:       }
340:     }
341: 
342:     const nostrilGeo = new THREE.SphereGeometry(headR * 0.05, 6, 4);
343:     for (const side of [-1, 1]) {
344:       const nostril = new THREE.Mesh(nostrilGeo, this.eyeMat);
345:       nostril.position.set(side * headR * 0.18, -headR * 0.02, headR * 1.86);
346:       headGroup.add(nostril);
347:     }
348: 
349:     if (g.crest > 0.18) {
350:       const crest = new THREE.Mesh(makeCrestGeometry(), this.crestMat);
351:       crest.scale.set(0.46 + g.crest * 0.55, 0.32 + g.crest * 0.5, 1);
352:       crest.position.set(0, headR * 0.28, -headR * 0.12);
353:       crest.rotation.set(0.18, Math.PI / 2, 0.02);
354:       crest.castShadow = true;
355:       headGroup.add(crest);
356:       this.crestMeshes.push(crest);
357: 
358:       const crestBrother = crest.clone();
359:       crestBrother.position.x = 0.008;
360:       headGroup.add(crestBrother);
361:     }
362: 
363:     // Neck frill when display alleles are strong.
364:     if (g.crest > 0.64) {
365:       for (const side of [-1, 1]) {
366:         const frill = new THREE.Mesh(new THREE.ConeGeometry(0.028, 0.16, 4), this.accentMat);
367:         frill.position.set(side * 0.095, neckLen * 0.72, 0);
368:         frill.rotation.z = side * 1.15;
369:         neckGroup.add(frill);
370:       }
371:     }
372:   }
