374:   buildTail({ bodyLen, bodyH, bodyY, tailLen }) {
375:     const g = this.genome;
376:     const base = new THREE.Group();
377:     base.position.set(0, bodyY + 0.01, -bodyLen * 0.77);
378:     base.rotation.x = -0.13;
379:     this.model.add(base);
380:     this.tailJoints.push(base);
381: 
382:     let parent = base;
383:     const segments = 5;
384:     const segLen = tailLen / segments;
385:     for (let i = 0; i < segments; i += 1) {
386:       const joint = new THREE.Group();
387:       joint.position.z = i === 0 ? 0 : -segLen;
388:       joint.rotation.x = i === 0 ? 0 : 0.035;
389:       parent.add(joint);
390:       const taper = 1 - (i / segments) * 0.82;
391:       const segment = new THREE.Mesh(this.torsoGeo, this.bodyMat);
392:       segment.scale.set(0.115 * taper, 0.105 * taper, segLen * 0.72);
393:       segment.position.z = -segLen * 0.5;
394:       segment.castShadow = true;
395:       joint.add(segment);
396:       this.tailJoints.push(joint);
397:       parent = joint;
398:     }
399: 
400:     if (g.armor > 0.58) {
401:       const club = new THREE.Mesh(new THREE.IcosahedronGeometry(0.12 + g.armor * 0.1, 0), this.boneMat);
402:       club.position.z = -segLen * 0.92;
403:       club.scale.set(1.2, 0.85, 1.35);
404:       club.rotation.set(0.2, 0.4, 0.1);
405:       club.castShadow = true;
406:       parent.add(club);
407:     }
408:   }
409: 
410:   buildLegs({ bodyLen, bodyW, bodyH, bodyY, legLen }) {
411:     const g = this.genome;
412:     const upperLen = legLen * 0.55;
413:     const lowerLen = legLen * 0.48;
414:     const legRadius = 0.058 + g.bodySize * 0.032;
415:     const positions = [
416:       { x: -bodyW * 0.82, z: bodyLen * 0.47, front: true, phase: 0 },
417:       { x: bodyW * 0.82, z: bodyLen * 0.47, front: true, phase: Math.PI },
418:       { x: -bodyW * 0.75, z: -bodyLen * 0.5, front: false, phase: Math.PI },
419:       { x: bodyW * 0.75, z: -bodyLen * 0.5, front: false, phase: 0 },
420:     ];
421: 
422:     positions.forEach((entry, i) => {
423:       const root = new THREE.Group();
424:       root.position.set(entry.x, bodyY - bodyH * 0.26, entry.z);
425:       this.model.add(root);
426: 
427:       const shoulder = new THREE.Mesh(this.torsoGeo, this.limbMat);
428:       shoulder.scale.set(legRadius * 1.22, legRadius * 1.25, legRadius * 1.3);
429:       root.add(shoulder);
430: 
431:       const thigh = new THREE.Mesh(this.torsoGeo, this.limbMat);
432:       thigh.scale.set(legRadius * 1.35, upperLen * 0.32, legRadius * 1.35);
433:       thigh.position.y = -upperLen * 0.36;
434:       thigh.castShadow = true;
435:       root.add(thigh);
436: 
437:       const upper = new THREE.Mesh(
438:         new THREE.CylinderGeometry(legRadius * 0.82, legRadius * 0.68, upperLen, 8),
439:         this.limbMat,
440:       );
441:       upper.position.y = -upperLen / 2;
442:       upper.castShadow = true;
443:       root.add(upper);
444: 
445:       const knee = new THREE.Group();
446:       knee.position.y = -upperLen;
447:       root.add(knee);
448: 
449:       const kneeJoint = new THREE.Mesh(this.torsoGeo, this.limbMat);
450:       kneeJoint.scale.setScalar(legRadius * 0.8);
451:       knee.add(kneeJoint);
452: 
453:       const lower = new THREE.Mesh(
454:         new THREE.CylinderGeometry(legRadius * 0.68, legRadius * 0.5, lowerLen, 7),
455:         this.limbMat,
456:       );
457:       lower.position.y = -lowerLen / 2;
458:       lower.castShadow = true;
459:       knee.add(lower);
460: 
461:       const foot = new THREE.Mesh(this.torsoGeo, this.limbMat);
462:       foot.scale.set(legRadius * 1.65, legRadius * 0.58, legRadius * 2.25);
463:       foot.position.set(0, -lowerLen - legRadius * 0.17, legRadius * 0.7);
464:       foot.castShadow = true;
465:       knee.add(foot);
466: 
467:       for (let toe = -1; toe <= 1; toe += 1) {
468:         const claw = new THREE.Mesh(new THREE.ConeGeometry(legRadius * 0.17, legRadius * 0.75, 4), this.darkBoneMat);
469:         claw.position.set(toe * legRadius * 0.62, -lowerLen + legRadius * 0.02, legRadius * 1.9);
470:         claw.rotation.x = Math.PI / 2.4;
471:         knee.add(claw);
472:       }
473: 
474:       this.legs.push({
475:         root,
476:         knee,
477:         phase: entry.phase,
478:         front: entry.front,
479:         upperLen,
480:         lowerLen,
481:         baseRot: entry.front ? 0.05 : -0.04,
482:       });
483:     });
484:   }
485: 
486:   buildArmor({ bodyLen, bodyW, bodyH, bodyY, legLen }) {
487:     const g = this.genome;
488:     if (g.armor < 0.22) return;
489:     const count = 3 + Math.round(g.armor * 5);
490:     for (let i = 0; i < count; i += 1) {
491:       const t = (i / (count - 1 || 1)) * 1.5 - 0.75;
492:       const z = t * bodyLen * 0.76;
493:       const profile = Math.sqrt(Math.max(0.06, 1 - Math.pow(t * 0.72, 2)));
494:       const height = (0.11 + g.armor * 0.26) * (0.7 + profile * 0.55);
495:       const spike = new THREE.Mesh(new THREE.ConeGeometry(0.045 + g.armor * 0.026, height, 4), this.boneMat);
496:       spike.position.set(0, bodyY + bodyH * profile * 0.93, z);
497:       spike.rotation.x = -0.34 - g.armor * 0.18;
498:       spike.rotation.y = Math.PI / 4;
499:       spike.castShadow = true;
500:       this.model.add(spike);
501:     }
502: 
503:     if (g.armor > 0.62) {
504:       for (const side of [-1, 1]) {
505:         const plate = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.18, 4), this.boneMat);
506:         plate.position.set(side * bodyW * 0.55, bodyY + bodyH * 0.5, bodyLen * 0.55);
507:         plate.rotation.z = side * 0.6;
508:         plate.rotation.x = -0.3;
509:         plate.castShadow = true;
510:         this.model.add(plate);
511:       }
512:     }
513:   }
514: 
515:   buildAccents({ bodyLen, bodyW, bodyH, bodyY }) {
516:     const g = this.genome;
517:     const spotCount = Math.round(1 + g.pattern * 5);
518:     for (let i = 0; i < spotCount; i += 1) {
519:       const side = i % 2 === 0 ? -1 : 1;
520:       const t = (i / Math.max(1, spotCount - 1)) * 1.4 - 0.7;
521:       const spot = new THREE.Mesh(new THREE.SphereGeometry(0.008 + g.pattern * 0.012, 6, 5), this.spotMat);
522:       spot.position.set(side * bodyW * 0.98, bodyY - bodyH * 0.05 + Math.sin(t * 3) * 0.03, t * bodyLen * 0.68);
523:       this.model.add(spot);
524:     }
525:   }
526: 
527:   buildCell() {
528:     const g = this.genome;
529:     this.sizeScale = 0.72 + g.bodySize * 0.3;
530:     this.dimensions = { bodyY: 0.1, neckLen: 0 };
531:     this.movementSpeed = 0;
532: 
533:     const cell = new THREE.Group();
534:     this.cellBody = new THREE.Mesh(new THREE.SphereGeometry(0.74, 32, 24), this.bodyMat);
535:     this.cellBody.scale.set(1, 0.9, 1);
536:     this.cellBody.castShadow = true;
537:     this.cellBody.receiveShadow = true;
538:     cell.add(this.cellBody);
539: 
540:     const membrane = new THREE.Mesh(
541:       new THREE.SphereGeometry(0.78, 32, 24),
542:       new THREE.MeshPhysicalMaterial({
543:         color: this.themeColor,
544:         transparent: true,
545:         opacity: 0.19,
546:         roughness: 0.22,
547:         metalness: 0.02,
548:         transmission: 0.18,
549:         thickness: 0.18,
550:         side: THREE.DoubleSide,
551:       }),
552:     );
553:     membrane.scale.set(1, 0.92, 1);
554:     cell.add(membrane);
555: 
556:     const nucleusMat = new THREE.MeshStandardMaterial({
557:       color: this.accentColor,
558:       emissive: this.accentColor,
559:       emissiveIntensity: 0.22,
560:       roughness: 0.48,
561:     });
562:     const nucleus = new THREE.Mesh(new THREE.SphereGeometry(0.3, 24, 18), nucleusMat);
563:     nucleus.position.set(-0.09, 0.04, 0.04);
564:     nucleus.scale.set(1, 0.93, 1.08);
565:     nucleus.castShadow = true;
566:     cell.add(nucleus);
567: 
568:     const nucleolus = new THREE.Mesh(
569:       new THREE.SphereGeometry(0.095, 16, 12),
570:       new THREE.MeshStandardMaterial({ color: 0xd7ff9a, emissive: 0x7dba4b, emissiveIntensity: 0.2, roughness: 0.4 }),
571:     );
572:     nucleolus.position.set(-0.02, 0.11, 0.16);
573:     cell.add(nucleolus);
