492:       const z = t * bodyLen * 0.76;
493:       const profile = Math.sqrt(Math.max(0.06, 1 - Math.pow(t * 0.72, 2)));
494:       const height = (0.11 + g.armor * 0.26) * (0.7 + profile * 0.55);
495:       const spike = new THREE.Mesh(new THREE.ConeGeometry(0.045 + g.armor * 0.026, height, 4), this.boneMat);
496:       spike.position.set(0, bodyY + bodyH * profile * 0.93, z);
497:       spike.rotation.x = -0.34 - g.armor * 0.18;
498:       spike.rotation.y = Math.PI / 4;
499:       spike.castShadow = true;
500:       this.model.add(spike);
