111:     this.position = new THREE.Vector3(position.x, terrainHeight(position.x, position.z), position.z);
112:     this.home = this.position.clone();
113:     this.group.position.copy(this.position);
114:     this.heading = rng() * TAU;
115:     this.group.rotation.y = this.heading;
116:     this.target = this.position.clone();
117:     this.walkPhase = rng() * TAU;
118:     this.blinkPhase = rng() * 8;
119:     this.moving = false;
120:     this.selected = false;
121:     this.dimensions = {};
122:     this.movementSpeed = 0.8;
123:     this.legs = [];
124:     this.tailJoints = [];
125:     this.eyes = [];
126:     this.crestMeshes = [];
127:     this.tempTarget = new THREE.Vector3();
128: 
129:     this.build();
130:     this.chooseTarget(true);
131:     if (index === 0) {
132:       this.heading = Math.atan2(
133:         world.camera.position.x - this.position.x,
134:         world.camera.position.z - this.position.z,
135:       );
136:       this.group.rotation.y = this.heading;
137:       this.target.set(
138:         this.position.x + Math.sin(this.heading) * 1.2,
139:         this.position.y,
140:         this.position.z + Math.cos(this.heading) * 1.2,
141:       );
142:     }
143:   }
144: 
145:   get radius() {
146:     return (0.58 + this.genome.bodySize * 0.42) * (0.82 + this.genome.bodySize * 0.5);
147:   }
148: 
149:   build() {
150:     const g = this.genome;
151:     const rng = this.rng;
152:     const sizeScale = 0.82 + g.bodySize * 0.55;
153:     this.sizeScale = sizeScale;
154:     this.model.scale.setScalar(0.01);
155:     this.spawnTime = this.world.time;
156: 
157:     const skin = makeSkinTexture(g, this.index + 3);
158:     this.skinTexture = skin.texture;
159:     const hue = skin.hue;
160:     const baseColor = new THREE.Color().setHSL(hue / 360, skin.saturation / 100, skin.lightness / 100, THREE.SRGBColorSpace);
161:     const accentColor = new THREE.Color().setHSL(((hue + 48) % 360) / 360, 0.46, 0.36, THREE.SRGBColorSpace);
162:     const bellyColor = new THREE.Color().setHSL(((hue + 14) % 360) / 360, 0.22, 0.57, THREE.SRGBColorSpace);
163:     const limbColor = new THREE.Color().setHSL(((hue - 2) % 360) / 360, 0.3, 0.28, THREE.SRGBColorSpace);
164:     this.themeColor = baseColor;
165:     this.accentColor = accentColor;
