171:       roughness: 0.76,
172:       metalness: 0.015,
173:       color: 0xffffff,
174:     });
175:     this.limbMat = new THREE.MeshStandardMaterial({
176:       color: limbColor,
177:       roughness: 0.83,
178:       metalness: 0.01,
