182:     this.darkBoneMat = new THREE.MeshStandardMaterial({ color: 0x6e6858, roughness: 0.84 });
183:     this.eyeMat = new THREE.MeshStandardMaterial({ color: 0x090d0a, roughness: 0.17, metalness: 0.12 });
