241:     chest.position.set(0, bodyY + 0.015, bodyLen * 0.58);
242:     chest.castShadow = true;
243:     this.model.add(chest);
244: 
245:     const hip = new THREE.Mesh(sphereGeo, this.bodyMat);
246:     hip.scale.set(bodyW * 0.86, bodyH * 0.84, bodyLen * 0.5);
247:     hip.position.set(0, bodyY + 0.005, -bodyLen * 0.58);
248:     hip.castShadow = true;
249:     this.model.add(hip);
