251:     const belly = new THREE.Mesh(sphereGeo, this.bellyMat);
252:     belly.scale.set(bodyW * 0.8, bodyH * 0.42, bodyLen * 0.86);
253:     belly.position.set(0, bodyY - bodyH * 0.38, bodyLen * 0.06);
254:     this.model.add(belly);
