527:   buildCell() {
528:     const g = this.genome;
529:     this.sizeScale = 0.72 + g.bodySize * 0.3;
530:     this.dimensions = { bodyY: 0.1, neckLen: 0 };
531:     this.movementSpeed = 0;
532: 
533:     const cell = new THREE.Group();
534:     this.cellBody = new THREE.Mesh(new THREE.SphereGeometry(0.74, 32, 24), this.bodyMat);
535:     this.cellBody.scale.set(1, 0.9, 1);
536:     this.cellBody.castShadow = true;
537:     this.cellBody.receiveShadow = true;
538:     cell.add(this.cellBody);
539: 
540:     const membrane = new THREE.Mesh(
541:       new THREE.SphereGeometry(0.78, 32, 24),
542:       new THREE.MeshPhysicalMaterial({
543:         color: this.themeColor,
544:         transparent: true,
545:         opacity: 0.19,
546:         roughness: 0.22,
547:         metalness: 0.02,
548:         transmission: 0.18,
549:         thickness: 0.18,
550:         side: THREE.DoubleSide,
551:       }),
552:     );
553:     membrane.scale.set(1, 0.92, 1);
554:     cell.add(membrane);
555: 
556:     const nucleusMat = new THREE.MeshStandardMaterial({
557:       color: this.accentColor,
558:       emissive: this.accentColor,
559:       emissiveIntensity: 0.22,
560:       roughness: 0.48,
561:     });
562:     const nucleus = new THREE.Mesh(new THREE.SphereGeometry(0.3, 24, 18), nucleusMat);
563:     nucleus.position.set(-0.09, 0.04, 0.04);
564:     nucleus.scale.set(1, 0.93, 1.08);
565:     nucleus.castShadow = true;
566:     cell.add(nucleus);
567: 
568:     const nucleolus = new THREE.Mesh(
569:       new THREE.SphereGeometry(0.095, 16, 12),
570:       new THREE.MeshStandardMaterial({ color: 0xd7ff9a, emissive: 0x7dba4b, emissiveIntensity: 0.2, roughness: 0.4 }),
571:     );
572:     nucleolus.position.set(-0.02, 0.11, 0.16);
573:     cell.add(nucleolus);
574: 
575:     const mitoMat = new THREE.MeshStandardMaterial({ color: 0xffc06d, emissive: 0x743c1f, emissiveIntensity: 0.18, roughness: 0.52 });
576:     const mitoGeo = new THREE.SphereGeometry(0.105, 14, 10);
577:     const rng = this.rng;
