578:     leafShape.moveTo(0, 0);
579:     leafShape.quadraticCurveTo(0.09, 0.32, 0.02, 0.9);
580:     leafShape.quadraticCurveTo(0, 1.0, -0.02, 0.9);
581:     leafShape.quadraticCurveTo(-0.09, 0.32, 0, 0);
582:     const leafGeo = new THREE.ShapeGeometry(leafShape, 8);
583:     leafGeo.rotateX(-Math.PI / 2);
584: 
585:     for (let i = 0; i < 24; i += 1) {
586:       const a = rng() * Math.PI * 2;
587:       const rr = 4.2 + rng() * 5.2;
588:       const x = Math.cos(a) * rr;
589:       const z = Math.sin(a) * rr;
590:       if (Math.hypot(x - POND.x, z - POND.z) < POND.radius + 0.35) continue;
591:       const fern = new THREE.Group();
592:       const scale = 0.48 + rng() * 0.72;
593:       fern.position.set(x, terrainHeight(x, z) + 0.025, z);
