27: function makeNoiseTexture(size = 512, base = "#b5b8a6", seed = 7) {
28:   const rng = mulberry32(seed);
29:   const canvas = document.createElement("canvas");
30:   canvas.width = size;
31:   canvas.height = size;
32:   const ctx = canvas.getContext("2d");
33:   ctx.fillStyle = base;
34:   ctx.fillRect(0, 0, size, size);
35:   for (let i = 0; i < 9000; i += 1) {
36:     const x = rng() * size;
37:     const y = rng() * size;
38:     const radius = 0.4 + rng() * 4.4;
39:     const shade = Math.floor(70 + rng() * 90);
40:     ctx.fillStyle = `rgba(${shade}, ${shade}, ${shade - 8}, ${0.04 + rng() * 0.14})`;
41:     ctx.beginPath();
42:     ctx.arc(x, y, radius, 0, Math.PI * 2);
43:     ctx.fill();
44:   }
45:   for (let i = 0; i < 170; i += 1) {
46:     const x = rng() * size;
47:     const y = rng() * size;
48:     ctx.strokeStyle = `rgba(55, 55, 48, ${0.03 + rng() * 0.09})`;
49:     ctx.lineWidth = 0.5 + rng() * 1.6;
50:     ctx.beginPath();
51:     ctx.moveTo(x, y);
52:     ctx.quadraticCurveTo(x + rng() * 25 - 12, y + rng() * 25 - 12, x + rng() * 48 - 24, y + rng() * 48 - 24);
53:     ctx.stroke();
54:   }
55:   const texture = new THREE.CanvasTexture(canvas);
56:   texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
57:   texture.colorSpace = THREE.SRGBColorSpace;
58:   texture.anisotropy = 4;
59:   return texture;
60: }
61: 
62: function makeRadialTexture(inner = "rgba(255,255,255,1)", outer = "rgba(255,255,255,0)", size = 128) {
63:   const canvas = document.createElement("canvas");
64:   canvas.width = size;
65:   canvas.height = size;
66:   const ctx = canvas.getContext("2d");
67:   const grad = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
68:   grad.addColorStop(0, inner);
69:   grad.addColorStop(0.3, inner);
70:   grad.addColorStop(1, outer);
71:   ctx.fillStyle = grad;
72:   ctx.fillRect(0, 0, size, size);
73:   const texture = new THREE.CanvasTexture(canvas);
74:   texture.colorSpace = THREE.SRGBColorSpace;
75:   return texture;
76: }
77: 
78: function makeGroundClearingTexture() {
79:   const size = 256;
80:   const canvas = document.createElement("canvas");
81:   canvas.width = size;
82:   canvas.height = size;
83:   const ctx = canvas.getContext("2d");
84:   const grad = ctx.createRadialGradient(size / 2, size / 2, size * 0.08, size / 2, size / 2, size * 0.5);
85:   grad.addColorStop(0, "rgba(111, 112, 73, 0.52)");
86:   grad.addColorStop(0.58, "rgba(98, 101, 66, 0.34)");
87:   grad.addColorStop(0.85, "rgba(78, 86, 58, 0.09)");
88:   grad.addColorStop(1, "rgba(78, 86, 58, 0)");
89:   ctx.fillStyle = grad;
90:   ctx.fillRect(0, 0, size, size);
91:   const rng = mulberry32(41);
92:   for (let i = 0; i < 130; i += 1) {
93:     const x = rng() * size;
94:     const y = rng() * size;
95:     ctx.fillStyle = `rgba(180, 170, 125, ${rng() * 0.06})`;
96:     ctx.beginPath();
97:     ctx.arc(x, y, rng() * 2.5, 0, Math.PI * 2);
98:     ctx.fill();
99:   }
100:   const texture = new THREE.CanvasTexture(canvas);
101:   texture.colorSpace = THREE.SRGBColorSpace;
102:   return texture;
103: }
