432:   buildPond() {
433:     const group = new THREE.Group();
434:     this.root.add(group);
435:     this.pondGroup = group;
436: 
437:     const shore = new THREE.Mesh(
438:       new THREE.RingGeometry(POND.radius * 0.92, POND.radius * 1.33, 56),
439:       new THREE.MeshStandardMaterial({ color: 0x6a6b4e, roughness: 0.98, side: THREE.DoubleSide }),
440:     );
441:     shore.rotation.x = -Math.PI / 2;
442:     shore.scale.set(1.2, 1, 0.82);
443:     shore.position.set(POND.x, 0.022, POND.z);
444:     shore.receiveShadow = true;
445:     group.add(shore);
446: 
447:     const waterMat = new THREE.MeshPhysicalMaterial({
448:       color: 0x0a4650,
449:       roughness: 0.14,
450:       metalness: 0.05,
451:       transmission: 0.16,
452:       transparent: true,
453:       opacity: 0.88,
454:       clearcoat: 1,
455:       clearcoatRoughness: 0.12,
456:       envMapIntensity: 0.4,
457:       side: THREE.DoubleSide,
458:     });
459:     const water = new THREE.Mesh(new THREE.CircleGeometry(POND.radius * 0.94, 64), waterMat);
460:     water.rotation.x = -Math.PI / 2;
461:     water.scale.set(1.18, 0.8, 1);
462:     water.position.set(POND.x, 0.075, POND.z);
463:     water.receiveShadow = true;
464:     group.add(water);
465:     this.water = water;
466: 
467:     for (let i = 0; i < 3; i += 1) {
468:       const ripple = new THREE.Mesh(
469:         new THREE.RingGeometry(0.35 + i * 0.33, 0.37 + i * 0.33, 64),
470:         new THREE.MeshBasicMaterial({ color: 0xa7ffe2, transparent: true, opacity: 0.2, side: THREE.DoubleSide }),
471:       );
472:       ripple.rotation.x = -Math.PI / 2;
473:       ripple.scale.set(1.2, 0.82, 1);
474:       ripple.position.set(POND.x - 0.25, 0.087, POND.z + 0.15);
475:       group.add(ripple);
476:       this.ripples.push({ mesh: ripple, offset: i * 0.95 });
477:     }
478: 
479:     const padMat = new THREE.MeshStandardMaterial({ color: 0x426f45, roughness: 0.86, side: THREE.DoubleSide });
480:     const padGeo = new THREE.CircleGeometry(0.2, 12);
481:     const padPositions = [
482:       [0.55, 0.25, 0.29],
483:       [-0.4, -0.4, 0.22],
484:       [0.2, -0.5, 0.16],
485:       [-0.65, 0.48, 0.18],
486:     ];
487:     for (const [dx, dz, s] of padPositions) {
488:       const pad = new THREE.Mesh(padGeo, padMat);
489:       pad.rotation.x = -Math.PI / 2;
490:       pad.rotation.z = Math.random() * 6;
491:       pad.scale.set(1.2 * s * 4, 1, s * 4);
492:       pad.position.set(POND.x + dx * 2, 0.092, POND.z + dz * 2);
493:       group.add(pad);
494:     }
495: 
496:     // Glowing mineral shards leaning out of the water.
497:     const shardMat = new THREE.MeshStandardMaterial({
498:       color: 0x38d5b6,
499:       emissive: 0x27c9a8,
500:       emissiveIntensity: 0.55,
501:       roughness: 0.24,
502:       metalness: 0.1,
503:       transparent: true,
504:       opacity: 0.82,
505:     });
506:     const shards = [
507:       [-0.95, 0.9, 0.28, 1.2],
508:       [-0.55, 1.15, 0.2, 0.8],
509:       [-1.2, 0.62, 0.15, 0.55],
510:     ];
511:     for (const [dx, dz, s, h] of shards) {
512:       const shard = new THREE.Mesh(new THREE.ConeGeometry(s, h, 5), shardMat);
513:       shard.position.set(POND.x + dx, 0.12 + h * 0.38, POND.z + dz);
514:       shard.rotation.z = -0.18 + Math.random() * 0.2;
515:       shard.rotation.x = 0.12;
516:       group.add(shard);
517:     }
518: 
519:     this.pondLight.position.set(POND.x, 0.7, POND.z);
520:   }
