579: function pickDominantPressure(org) {
580:   const weights = org.evaluation.weights;
581:   const entries = Object.entries(weights).sort((a, b) => b[1] - a[1]);
582:   const labels = {
583:     thermal: "thermoregulation",
584:     foraging: "forage access",
585:     defense: "predator defense",
586:     efficiency: "metabolic efficiency",
587:   };
588:   return labels[entries[0][0]];
589: }
