571:     );
572:     nucleolus.position.set(-0.02, 0.11, 0.16);
573:     cell.add(nucleolus);
574: 
575:     const mitoMat = new THREE.MeshStandardMaterial({ color: 0xffc06d, emissive: 0x743c1f, emissiveIntensity: 0.18, roughness: 0.52 });
576:     const mitoGeo = new THREE.SphereGeometry(0.105, 14, 10);
577:     const rng = this.rng;
578:     for (let i = 0; i < 5; i += 1) {
579:       const angle = (i / 5) * TAU + 0.35;
580:       const organelle = new THREE.Mesh(mitoGeo, mitoMat);
581:       organelle.position.set(Math.cos(angle) * 0.46, (rng() - 0.5) * 0.34, Math.sin(angle) * 0.46);
582:       organelle.scale.set(1.7, 0.72, 0.8);
583:       organelle.rotation.y = -angle;
584:       organelle.castShadow = true;
585:       cell.add(organelle);
