535:   buildGrass(group, rng) {
536:     const count = 2600;
537:     const bladeGeo = new THREE.ConeGeometry(0.014, 0.46, 3, 1);
538:     bladeGeo.translate(0, 0.23, 0);
539:     const bladeMat = new THREE.MeshStandardMaterial({
540:       color: 0x6b8c4c,
541:       roughness: 0.93,
542:       side: THREE.DoubleSide,
543:     });
544:     const grass = new THREE.InstancedMesh(bladeGeo, bladeMat, count);
545:     grass.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
546:     const dummy = new THREE.Object3D();
547:     const color = new THREE.Color();
548:     let placed = 0;
549:     let guard = 0;
550:     while (placed < count && guard < count * 14) {
551:       guard += 1;
552:       const a = rng() * Math.PI * 2;
553:       const rr = Math.sqrt(rng()) * 9.7;
554:       const x = Math.cos(a) * rr;
555:       const z = Math.sin(a) * rr;
556:       const pondD = Math.hypot(x - POND.x, z - POND.z);
557:       if (pondD < POND.radius * 1.12) continue;
558:       if (Math.hypot(x, z) < 2.2) continue;
559:       const clearing = smooth(2.2, 4.3, Math.hypot(x, z));
560:       if (rng() > 0.22 + clearing * 0.78) continue;
561:       const scale = 0.55 + rng() * 1.25 + clearing * 0.35;
562:       dummy.position.set(x, terrainHeight(x, z) - 0.01, z);
563:       dummy.rotation.set((rng() - 0.5) * 0.25, rng() * Math.PI * 2, (rng() - 0.5) * 0.24);
564:       dummy.scale.set(0.7 + rng() * 0.7, scale, 0.7 + rng() * 0.7);
565:       dummy.updateMatrix();
566:       grass.setMatrixAt(placed, dummy.matrix);
567:       color.setHSL(0.2 + rng() * 0.05, 0.25 + rng() * 0.24, 0.28 + rng() * 0.16);
568:       grass.setColorAt(placed, color);
569:       placed += 1;
570:     }
571:     grass.count = placed;
572:     grass.receiveShadow = true;
573:     group.add(grass);
574:   }
575: 
576:   buildFerns(group, rng) {
577:     const leafShape = new THREE.Shape();
578:     leafShape.moveTo(0, 0);
579:     leafShape.quadraticCurveTo(0.09, 0.32, 0.02, 0.9);
580:     leafShape.quadraticCurveTo(0, 1.0, -0.02, 0.9);
581:     leafShape.quadraticCurveTo(-0.09, 0.32, 0, 0);
582:     const leafGeo = new THREE.ShapeGeometry(leafShape, 8);
583:     leafGeo.rotateX(-Math.PI / 2);
584: 
585:     for (let i = 0; i < 24; i += 1) {
586:       const a = rng() * Math.PI * 2;
587:       const rr = 4.2 + rng() * 5.2;
588:       const x = Math.cos(a) * rr;
589:       const z = Math.sin(a) * rr;
590:       if (Math.hypot(x - POND.x, z - POND.z) < POND.radius + 0.35) continue;
591:       const fern = new THREE.Group();
592:       const scale = 0.48 + rng() * 0.72;
593:       fern.position.set(x, terrainHeight(x, z) + 0.025, z);
594:       fern.rotation.y = rng() * Math.PI * 2;
595:       const leafCount = 6 + Math.floor(rng() * 5);
596:       const leafMat = new THREE.MeshStandardMaterial({
597:         color: new THREE.Color().setHSL(0.25 + rng() * 0.035, 0.42, 0.22 + rng() * 0.09),
598:         roughness: 0.86,
599:         side: THREE.DoubleSide,
600:       });
601:       for (let l = 0; l < leafCount; l += 1) {
602:         const leaf = new THREE.Mesh(leafGeo, leafMat);
603:         const angle = (l / leafCount) * Math.PI * 2 + rng() * 0.25;
604:         leaf.rotation.y = angle;
605:         leaf.rotation.z = 0.48 + rng() * 0.42;
606:         leaf.position.y = 0.03;
607:         leaf.scale.setScalar(scale * (0.75 + rng() * 0.35));
608:         leaf.castShadow = true;
609:         fern.add(leaf);
610:       }
611:       group.add(fern);
612:     }
613:   }
