374:   buildTail({ bodyLen, bodyH, bodyY, tailLen }) {
375:     const g = this.genome;
376:     const base = new THREE.Group();
377:     base.position.set(0, bodyY + 0.01, -bodyLen * 0.77);
378:     base.rotation.x = -0.13;
379:     this.model.add(base);
380:     this.tailJoints.push(base);
381: 
382:     let parent = base;
383:     const segments = 5;
384:     const segLen = tailLen / segments;
385:     for (let i = 0; i < segments; i += 1) {
386:       const joint = new THREE.Group();
387:       joint.position.z = i === 0 ? 0 : -segLen;
388:       joint.rotation.x = i === 0 ? 0 : 0.035;
389:       parent.add(joint);
390:       const taper = 1 - (i / segments) * 0.82;
391:       const segment = new THREE.Mesh(this.torsoGeo, this.bodyMat);
392:       segment.scale.set(0.115 * taper, 0.105 * taper, segLen * 0.72);
393:       segment.position.z = -segLen * 0.5;
394:       segment.castShadow = true;
395:       joint.add(segment);
396:       this.tailJoints.push(joint);
397:       parent = joint;
398:     }
399: 
400:     if (g.armor > 0.58) {
401:       const club = new THREE.Mesh(new THREE.IcosahedronGeometry(0.12 + g.armor * 0.1, 0), this.boneMat);
402:       club.position.z = -segLen * 0.92;
403:       club.scale.set(1.2, 0.85, 1.35);
404:       club.rotation.set(0.2, 0.4, 0.1);
405:       club.castShadow = true;
406:       parent.add(club);
407:     }
408:   }
