792:     const dotTexture = makeRadialTexture("rgba(195,255,221,1)", "rgba(150,255,210,0)", 64);
793: 
794:     const sporeCount = 240;
795:     const positions = new Float32Array(sporeCount * 3);
796:     for (let i = 0; i < sporeCount; i += 1) {
797:       const a = rng() * Math.PI * 2;
798:       const rr = Math.sqrt(rng()) * 11;
799:       positions[i * 3] = Math.cos(a) * rr;
