680: function directMutation(gene = null) {
681:   if (state.transitioning) return;
682:   hideHint();
683:   const org = currentOrganism();
684:   const creature = creatures.selected;
685:   if (!org || !creature) return;
686:   if (state.mutagen <= 0) {
687:     showToast("Mutagen reserve depleted", "Advance a generation to replenish the reserve", "!", 3000);
688:     audio.error();
689:     return;
690:   }
691: 
692:   const key = gene || TRAIT_ROWS[Math.floor(random() * TRAIT_ROWS.length)];
693:   const result = mutateGene(org.genome, key, random, 0.17);
694:   org.genome = result.genome;
695:   org.evaluation = evaluate(org.genome, state.env, org.condition);
696:   org.changes = result.changes;
697:   state.mutagen -= 1;
698:   creatures.replace(creatures.selectedIndex, org);
699:   const mutated = creatures.selected;
700:   world.burst(mutated.position, mutated.accentColor ?? 0xcaff72, 0.75);
701: 
702:   const change = result.changes[0];
703:   const info = describeChange(change);
704:   showToast(info.title, `${info.detail} · directed mutation expressed`, "⌁", 3300);
705:   addLog(`Directed mutation: <b>${info.title}</b> in specimen K-${pad(creatures.selectedIndex + 1)}.`, true);
706:   if (state.history.length) state.history[state.history.length - 1] = meanFitness();
707:   updateAll();
708:   audio.mutate();
709: }
