591: function advanceGeneration({ automatic = false } = {}) {
592:   if (state.transitioning) return;
593:   hideHint();
594:   state.transitioning = true;
595:   const before = meanFitness();
596:   const parents = rankPopulation(state.population);
597:   const seeded = breedPopulation(state.population, state.env, random);
598:   const nextOrganisms = seeded.map((item) => makeOrganism(item.genome, {
599:     origin: item.origin,
600:     changes: item.changes,
601:     parents: item.parents,
602:   }));
603: 
604:   state.population = nextOrganisms;
605:   const previousStage = state.stage;
606:   state.generation += 1;
607:   state.stage = state.generation >= 4 ? "organism" : "cellular";
608:   state.mutagen = Math.min(5, state.mutagen + 2);
609:   state.autoTimer = 0;
610:   creatures.selectedIndex = 0;
611:   creatures.spawnPopulation(state.population, SPAWN_POSITIONS, state.stage);
612:   creatures.select(0, true);
613: 
614:   recordHistory();
615:   const mean = meanFitness();
616:   const top = rankPopulation(state.population)[0];
617:   const pressure = pickDominantPressure(top);
618:   const changes = nextOrganisms.flatMap((org) => org.changes || []);
619:   const strongest = changes.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta))[0];
620: 
621:   els.btnAuto.classList.toggle("paused", !state.auto);
622: 
623:   addLog(
624:     `Generation ${pad(state.generation)} ${state.stage === "organism" && previousStage === "cellular" ? "developed into multicellular organisms" : "hatched"}. Mean fitness <b>${mean.toFixed(1)}</b>; ${pressure} led selection.`,
625:     true,
626:   );
627:   if (strongest) {
628:     const desc = describeChange(strongest);
629:     addLog(`Dominant mutation: ${desc.detail.toLowerCase()} — ${desc.title}.`);
630:   } else {
631:     addLog(`The leading genome was preserved intact. ${parents.length ? "Stability can be a strategy." : ""}`);
632:   }
633: 
634:   const selectedCreature = creatures.selected;
635:   if (selectedCreature) {
636:     world.burst(selectedCreature.position, selectedCreature.accentColor ?? 0xcaff72, 1.15);
637:   }
638: 
639:   const gain = mean - before;
640:   showToast(
641:     previousStage !== state.stage ? "Organism stage reached" : `Generation ${pad(state.generation)} hatched`,
642:     previousStage !== state.stage
643:       ? `Cell lineages now develop into multicellular organisms · ${gain >= 0 ? "+" : "−"}${Math.abs(gain).toFixed(1)} fitness`
644:       : `${gain >= 0 ? "+" : "−"}${Math.abs(gain).toFixed(1)} fitness · ${state.population.filter((o) => o.changes.length).length} new alleles`,
645:     strongest ? "◈" : "✦",
646:     3600,
647:   );
648:   if (automatic) addLog("Automatic selection advanced the lineage.");
649:   updateAll();
650:   audio.evolve();
651: 
652:   if (!state.milestoneShown && state.generation >= 5 && mean >= 72) {
653:     state.milestoneShown = true;
654:     setTimeout(() => {
655:       showToast("Stable lineage established", `${mean.toFixed(1)} mean fitness · the basin is adapting around your creatures`, "❖", 5200);
656:       addLog("Milestone: a stable lineage now occupies the basin.", true);
657:     }, 900);
658:   }
659: 
660:   setTimeout(() => {
661:     state.transitioning = false;
662:   }, 360);
663: }
