608:   chooseTarget(initial = false) {
609:     const angle = this.rng() * TAU;
610:     const dist = initial ? 0 : (this.index === 0 ? 0.8 : 1.1) + this.rng() * (this.index === 0 ? 1.7 : 2.2);
611:     let x = this.home.x + Math.cos(angle) * dist;
612:     let z = this.home.z + Math.sin(angle) * dist;
613: 
614:     if (Math.hypot(x - POND.x, z - POND.z) < POND.radius + 0.8) {
615:       x = this.home.x - Math.cos(angle) * dist;
616:       z = this.home.z - Math.sin(angle) * dist;
617:     }
618:     const r = Math.hypot(x, z);
619:     if (r > 7.1) {
620:       x *= 7.1 / r;
621:       z *= 7.1 / r;
622:     }
623:     this.target.set(x, 0, z);
624:   }
625: 
626:   update(dt) {
627:     const elapsed = this.world.time - this.spawnTime;
628:     const spawnT = clamp01(elapsed / 0.8);
629:     this.model.scale.setScalar(this.sizeScale * Math.max(0.01, easeOutBack(spawnT)));
630:     this.model.visible = spawnT > 0;
631:     if (spawnT < 1) {
632:       this.model.rotation.z = Math.sin(spawnT * Math.PI) * 0.04;
633:       return;
634:     }
635:     this.model.rotation.z *= 0.9;
636: 
637:     if (this.stage === "cellular") {
638:       const time = this.world.time;
639:       this.model.position.y = Math.sin(time * 1.3 + this.index) * 0.035;
640:       this.cellGroup.rotation.y = time * 0.12 + this.index * 0.4;
641:       this.cellNucleus.scale.setScalar(1 + Math.sin(time * 1.7 + this.index) * 0.025);
642:       this.cellOrganelles.forEach((organelle, index) => {
643:         organelle.rotation.y += dt * (index % 2 ? -0.12 : 0.16);
644:       });
645:       this.position.y = terrainHeight(this.position.x, this.position.z);
646:       this.group.position.y = this.position.y;
647:       return;
648:     }
649: 
650:     const speedGene = 0.6 + this.genome.speed * 1.45;
651:     this.tempTarget.set(this.target.x - this.position.x, 0, this.target.z - this.position.z);
652:     const distance = this.tempTarget.length();
653:     if (distance < 0.22 || this.rng() < dt * 0.008) {
654:       this.chooseTarget();
655:     }
656: 
657:     const moving = distance > 0.35;
658:     this.moving = moving;
659:     if (moving) {
660:       this.tempTarget.normalize();
661:       const desired = Math.atan2(this.tempTarget.x, this.tempTarget.z);
662:       let diff = desired - this.heading;
663:       while (diff > Math.PI) diff -= TAU;
664:       while (diff < -Math.PI) diff += TAU;
665:       this.heading += diff * Math.min(1, dt * 2.4);
666:       this.group.rotation.y = this.heading;
667: 
668:       const step = Math.min(distance, dt * (0.16 + speedGene * 0.22));
669:       const nx = this.position.x + Math.sin(this.heading) * step;
670:       const nz = this.position.z + Math.cos(this.heading) * step;
671:       if (Math.hypot(nx - POND.x, nz - POND.z) > POND.radius + 0.5 && Math.hypot(nx, nz) < 7.35) {
672:         this.position.x = nx;
673:         this.position.z = nz;
674:       } else {
675:         this.chooseTarget();
676:       }
677:       this.walkPhase += dt * (3.9 + speedGene * 2.8);
678:     } else {
679:       this.walkPhase += dt * 1.1;
680:     }
681: 
682:     this.position.y = terrainHeight(this.position.x, this.position.z);
683:     this.group.position.x = this.position.x;
684:     this.group.position.z = this.position.z;
685:     this.group.position.y = this.position.y;
686: 
687:     const stride = moving ? 1 : 0.25;
688:     for (const leg of this.legs) {
689:       const swing = Math.sin(this.walkPhase + leg.phase) * 0.54 * stride;
690:       const lift = Math.max(0, Math.sin(this.walkPhase + leg.phase + Math.PI / 2)) * 0.28 * stride;
691:       leg.root.rotation.x = leg.baseRot + swing;
692:       leg.knee.rotation.x = -lift + (leg.front ? 0.18 : 0.32);
693:     }
694: 
695:     const bob = moving ? Math.abs(Math.sin(this.walkPhase)) * 0.026 : Math.sin(this.world.time * 1.4) * 0.006;
696:     this.model.position.y = bob;
697:     this.model.rotation.x = moving ? Math.sin(this.walkPhase) * 0.008 : 0;
698: 
699:     if (this.neckGroup) {
700:       this.neckGroup.rotation.z = Math.sin(this.walkPhase * 0.5 + 1.2) * 0.022;
701:       this.neckGroup.rotation.x = (0.62 + this.genome.neck * 0.2) + Math.sin(this.walkPhase * 0.5) * 0.027;
702:     }
703:     if (this.headGroup) {
704:       this.headGroup.rotation.y = Math.sin(this.world.time * 0.7 + this.index) * 0.11;
705:       this.headGroup.rotation.z = Math.sin(this.walkPhase * 0.5) * 0.02;
706:     }
707:     for (let i = 1; i < this.tailJoints.length; i += 1) {
708:       const joint = this.tailJoints[i];
709:       joint.rotation.y = Math.sin(this.world.time * 1.7 + i * 0.8 + this.index) * (0.06 + i * 0.012);
710:       joint.rotation.x = 0.035 + Math.sin(this.world.time * 1.1 + i) * 0.012;
711:     }
712:     for (const crest of this.crestMeshes) {
713:       crest.rotation.y = Math.PI / 2 + Math.sin(this.world.time * 2.1 + this.index) * 0.035;
714:     }
715: 
716:     const blink = (this.world.time + this.blinkPhase) % 4.6;
717:     const closed = blink > 4.42 ? 0.12 : 1;
718:     for (const eye of this.eyes) {
719:       eye.scale.y = eye.userData.baseScaleY * closed;
720:     }
721:   }
722: 
723:   setVisible(value) {
724:     this.group.visible = value;
725:   }
726: 
727:   dispose() {
728:     this.world.removeLifeObject(this.group);
729:     const disposed = new Set();
730:     this.group.traverse((obj) => {
731:       if (obj.geometry && !disposed.has(obj.geometry)) {
732:         disposed.add(obj.geometry);
733:         obj.geometry.dispose();
734:       }
735:       if (obj.material) {
736:         const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
737:         for (const mat of mats) {
738:           if (mat.map && !disposed.has(mat.map)) {
739:             disposed.add(mat.map);
740:             mat.map.dispose();
741:           }
742:           if (!disposed.has(mat)) {
743:             disposed.add(mat);
744:             mat.dispose();
745:           }
746:         }
747:       }
748:     });
749:     this.skinTexture?.dispose();
750:   }
751: }
