753: export class CreatureSystem {
754:   constructor(world) {
755:     this.world = world;
756:     this.creatures = [];
757:     this.selectedIndex = 0;
758:     this.rand = mulberry32(911);
759:     this.raycaster = new THREE.Raycaster();
760:     this.pointer = new THREE.Vector2();
761:   }
762: 
763:   spawnPopulation(population, positions, stage = "organism") {
764:     for (const creature of this.creatures) {
765:       creature.dispose();
766:     }
767:     this.creatures = [];
768:     population.forEach((organism, index) => {
769:       const creature = new Creature({
770:         genome: organism.genome,
771:         evaluation: organism.evaluation,
772:         world: this.world,
773:         rng: mulberry32(3001 + index * 137 + organism.id * 13),
774:         index,
775:         position: positions[index],
776:         stage,
777:       });
778:       organism.creature = creature;
779:       this.creatures.push(creature);
780:     });
