576:   buildFerns(group, rng) {
577:     const leafShape = new THREE.Shape();
578:     leafShape.moveTo(0, 0);
579:     leafShape.quadraticCurveTo(0.09, 0.32, 0.02, 0.9);
580:     leafShape.quadraticCurveTo(0, 1.0, -0.02, 0.9);
581:     leafShape.quadraticCurveTo(-0.09, 0.32, 0, 0);
582:     const leafGeo = new THREE.ShapeGeometry(leafShape, 8);
583:     leafGeo.rotateX(-Math.PI / 2);
584: 
585:     for (let i = 0; i < 24; i += 1) {
586:       const a = rng() * Math.PI * 2;
587:       const rr = 4.2 + rng() * 5.2;
588:       const x = Math.cos(a) * rr;
589:       const z = Math.sin(a) * rr;
590:       if (Math.hypot(x - POND.x, z - POND.z) < POND.radius + 0.35) continue;
591:       const fern = new THREE.Group();
592:       const scale = 0.48 + rng() * 0.72;
593:       fern.position.set(x, terrainHeight(x, z) + 0.025, z);
594:       fern.rotation.y = rng() * Math.PI * 2;
595:       const leafCount = 6 + Math.floor(rng() * 5);
596:       const leafMat = new THREE.MeshStandardMaterial({
597:         color: new THREE.Color().setHSL(0.25 + rng() * 0.035, 0.42, 0.22 + rng() * 0.09),
598:         roughness: 0.86,
599:         side: THREE.DoubleSide,
600:       });
601:       for (let l = 0; l < leafCount; l += 1) {
602:         const leaf = new THREE.Mesh(leafGeo, leafMat);
603:         const angle = (l / leafCount) * Math.PI * 2 + rng() * 0.25;
604:         leaf.rotation.y = angle;
605:         leaf.rotation.z = 0.48 + rng() * 0.42;
606:         leaf.position.y = 0.03;
607:         leaf.scale.setScalar(scale * (0.75 + rng() * 0.35));
608:         leaf.castShadow = true;
609:         fern.add(leaf);
610:       }
611:       group.add(fern);
612:     }
613:   }
