984:     creature.position.z,
985:   );
986:   tagWorld.project(world.camera);
987:   if (tagWorld.z > 1 || tagWorld.z < -1) {
988:     els.creatureTag.style.opacity = "0";
989:     return;
990:   }
991:   const x = (tagWorld.x * 0.5 + 0.5) * window.innerWidth;
992:   const y = (-tagWorld.y * 0.5 + 0.5) * window.innerHeight;
993:   const covered = window.innerWidth > 900 && (x < 345 || x > window.innerWidth - 345);
994:   els.creatureTag.style.opacity = covered ? "0" : "1";
995:   els.creatureTag.style.left = `${x}px`;
