999: function gameLoop(now) {
1000:   const rawDt = Math.min(1, (now - (gameLoop.last || now)) / 1000);
1001:   const dt = Math.min(0.05, rawDt);
1002:   gameLoop.last = now;
1003:   creatures.update(dt);
1004:   updateCreatureTag();
1005: 
1006:   if (state.auto) {
1007:     // Auto-evolution runs on wall-clock time so software rendering or a
1008:     // slow frame never stretches "one generation every N seconds".
1009:     state.autoTimer += rawDt * state.speed;
